/* From Uiverse.io by ICe1BotMaker - Tags: switch, modern, toggle switch */
.__UIV_SCOPE__ label[for="check"] input {
  display: none;
}

.__UIV_SCOPE__ label[for="check"] .check-bg {
  width: 50px;
  padding: 2.5px;
  background: whitesmoke;
  border-radius: 100px;
  border: 1px solid rgb(228, 228, 228);
  transition: background .1s, border .1s;
}

.__UIV_SCOPE__ label[for="check"] .check-span {
  display: block;
  background: rgb(219, 219, 219);
  width: 25px;
  height: 25px;
  border-radius: 100%;
  transition: background .1s, border .1s, margin-left .325s;
}

.__UIV_SCOPE__ label[for="check"] input:checked ~ .check-bg {
  background: rgb(81, 107, 255);
  border: 1px solid rgb(68, 90, 216);
}

.__UIV_SCOPE__ label[for="check"] input:checked ~ .check-bg .check-span {
  background: white;
  border: 0;
  margin-left: 18px;
}
